<template>
  <section>
    <div class="d-flex justify-content-between align-items-center mb-3"><RouterLink :to="`/lms/courses/${course.id}`"><i class="bi bi-arrow-left me-1"></i>Quay lại khóa học</RouterLink><span class="badge badge-soft-success">Đã xem {{ Math.round(progress.watchPercent) }}%</span></div>
    <div v-if="loading" class="app-card p-5 text-center"><span class="spinner-border text-success"></span><p class="text-secondary mt-3 mb-0">Đang tải bài học...</p></div>
    <div v-else-if="error" class="app-card p-5 text-center"><i class="bi bi-exclamation-circle fs-1 text-danger"></i><h1 class="h4 mt-3">Không thể mở bài học</h1><p class="text-secondary">{{ error }}</p><button class="btn btn-brand" @click="loadPlayer">Thử lại</button></div>
    <template v-else>
      <div class="player-grid app-card overflow-hidden">
        <div class="video-area">
          <div class="video-stage">
            <video v-if="video.url" ref="videoRef" :src="video.url" :poster="video.poster || undefined" controls preload="metadata" :controlslist="video.allowSeek?'':'noplaybackrate'" @loadedmetadata="resumeVideo" @timeupdate="handleTimeUpdate" @seeking="protectSeek" @ratechange="protectSpeed" @pause="saveProgress"><track kind="captions"></video>
            <div v-else class="video-empty"><i class="bi bi-camera-video-off"></i><strong>Video chưa sẵn sàng</strong><span>Giảng viên chưa tải file video cho bài học này.</span></div>
            <button v-for="item in interactions" :key="item.id" type="button" class="video-marker" :class="{answered:item.answered}" :style="{left:markerPercent(item.time)+'%'}" :title="`${formatTime(item.time)} — ${item.label}`" @click="openQuestion(item)"></button>
          </div>
          <div class="lesson-meta"><div><span class="badge badge-soft-primary">{{ lesson.type }}</span><h1>{{ lesson.title }}</h1><p>{{ lesson.description || 'Học qua video và hoàn thành các câu hỏi tương tác.' }}</p></div><div class="score"><strong>{{ currentScore }}</strong><small>Điểm hiện tại</small></div></div>
        </div>
        <aside class="content-panel"><div class="p-3"><strong>Nội dung khóa học</strong><small class="d-block text-secondary">{{ completedLessons }}/{{ lessonCount }} bài đã hoàn thành</small></div><div class="chapter-list"><div v-for="chapter in chapters" :key="chapter.id" class="chapter"><strong>{{ chapter.title }}</strong><RouterLink v-for="item in chapter.lessons" :key="item.id" :to="`/lms/courses/${course.id}/lessons/${item.id}`" :class="{active:item.id===lesson.id}"><i :class="['bi',item.completed?'bi-check-circle-fill':item.id===lesson.id?'bi-play-circle':'bi-circle']"></i><span>{{ item.title }}</span><small>{{ formatTime(item.duration) }}</small></RouterLink></div></div></aside>
      </div>
      <div class="app-card p-4 mt-4"><h2 class="h5 fw-bold">Mốc câu hỏi tương tác</h2><div v-if="interactions.length" class="interaction-list"><button v-for="item in interactions" :key="item.id" type="button" :class="{answered:item.answered}" @click="openQuestion(item)"><span>{{ formatTime(item.time) }}</span><i :class="['bi',item.answered?'bi-check-circle-fill':'bi-patch-question']"></i><div><strong>{{ item.label }}</strong><small>{{ item.type }} • {{ item.score }} điểm</small></div></button></div><p v-else class="text-secondary mb-0">Bài học này không có câu hỏi tương tác.</p></div>
    </template>

    <div v-if="activeQuestion" class="modal-backdrop-custom" @click.self="closeQuestion">
      <div class="question-modal app-card">
        <button v-if="canSkipQuestion" class="close" @click="closeQuestion"><i class="bi bi-x-lg"></i></button>
        <span class="badge badge-soft-warning">Câu hỏi tại {{ formatTime(activeQuestion.time) }}</span><h2>{{ activeQuestion.label }}</h2><p v-if="activeQuestion.description" class="text-secondary">{{ activeQuestion.description }}</p>
        <template v-if="!answerResult">
          <label v-for="option in activeQuestion.options" :key="option.code" class="answer"><input v-if="activeQuestion.type==='MULTIPLE_CHOICE'" v-model="multipleAnswers" type="checkbox" :value="option.code"><input v-else v-model="singleAnswer" type="radio" :value="option.code"><span>{{ option.code }}</span>{{ option.text }}</label>
          <textarea v-if="activeQuestion.type==='SHORT_ANSWER'" v-model.trim="shortAnswer" class="form-control" rows="4" placeholder="Nhập câu trả lời của bạn..."></textarea>
          <div v-if="answerError" class="alert alert-danger mt-3 mb-0">{{ answerError }}</div>
          <button class="btn btn-brand w-100 mt-3" :disabled="submitting||!hasAnswer" @click="submitAnswer"><span v-if="submitting" class="spinner-border spinner-border-sm me-1"></span>Gửi câu trả lời</button>
        </template>
        <div v-else class="answer-result" :class="answerResult.isCorrect===true?'correct':answerResult.isCorrect===false?'wrong':'pending'"><i :class="['bi',answerResult.isCorrect===true?'bi-check-circle-fill':answerResult.isCorrect===false?'bi-x-circle-fill':'bi-hourglass-split']"></i><h3>{{ answerResult.isCorrect===true?'Chính xác!':answerResult.isCorrect===false?'Chưa chính xác':'Đang chờ giảng viên chấm' }}</h3><strong>+{{ answerResult.score }} điểm</strong><p v-if="answerResult.explanation">{{ answerResult.explanation }}</p><button class="btn btn-brand w-100 mt-2" @click="continueVideo">Tiếp tục bài học</button></div>
      </div>
    </div>
  </section>
</template>

<script setup>
import { computed,onBeforeUnmount,onMounted,reactive,ref } from 'vue'
import { useRoute } from 'vue-router'
import axiosClient from '../../api/axiosClient'
import { resolveApiAssetUrl } from '../../api/apiConfig'
import { formatInteractionTime,shouldTriggerInteraction } from '../../utils/learningRules'

const route=useRoute(),videoRef=ref(null),loading=ref(true),error=ref(''),interactions=ref([]),chapters=ref([]),activeQuestion=ref(null),singleAnswer=ref(''),multipleAnswers=ref([]),shortAnswer=ref(''),submitting=ref(false),answerError=ref(''),answerResult=ref(null)
const lesson=reactive({id:0,title:'',description:'',type:'VIDEO',duration:0,passingScore:0}),course=reactive({id:0,title:''}),video=reactive({id:0,url:'',poster:'',duration:0,allowSeek:false,allowSpeed:true,requiredWatchPercent:80}),progress=reactive({currentTime:0,maxWatchedTime:0,watchPercent:0})
const pick=(source,...names)=>names.map(name=>source?.[name]).find(value=>value!==undefined&&value!==null)
const formatTime=formatInteractionTime
const currentScore=ref(0),previousTime=ref(0),lastSavedAt=ref(0),savingProgress=ref(false),triggered=new Set()
const lessonCount=computed(()=>chapters.value.reduce((total,chapter)=>total+chapter.lessons.length,0)),completedLessons=computed(()=>chapters.value.reduce((total,chapter)=>total+chapter.lessons.filter(x=>x.completed).length,0))
const canSkipQuestion=computed(()=>activeQuestion.value?.allowSkip||!activeQuestion.value?.required)
const hasAnswer=computed(()=>activeQuestion.value?.type==='MULTIPLE_CHOICE'?multipleAnswers.value.length>0:activeQuestion.value?.type==='SHORT_ANSWER'?Boolean(shortAnswer.value):Boolean(singleAnswer.value))

onMounted(loadPlayer)
onBeforeUnmount(()=>{void saveProgress()})
async function loadPlayer(){loading.value=true;error.value='';try{const data=await axiosClient.get(`/lms/lessons/${Number(route.params.lessonId)}/player`,{params:{_fresh:Date.now()}});const l=pick(data,'lesson','Lesson')||{},c=pick(data,'course','Course')||{},v=pick(data,'video','Video')||{},p=pick(data,'progress','Progress')||{};Object.assign(lesson,{id:Number(pick(l,'Id','id')),title:pick(l,'Title','title')||'',description:pick(l,'Description','description')||'',type:pick(l,'LessonType','lessonType')||'VIDEO',duration:Number(pick(l,'DurationSeconds','durationSeconds')||0),passingScore:Number(pick(l,'PassingScore','passingScore')||0)});Object.assign(course,{id:Number(pick(c,'Id','id')),title:pick(c,'Title','title')||''});Object.assign(video,{id:Number(pick(v,'Id','id')||0),url:resolveApiAssetUrl(pick(v,'VideoUrl','videoUrl')||''),poster:resolveApiAssetUrl(pick(v,'PosterUrl','posterUrl')||''),duration:Number(pick(v,'DurationSeconds','durationSeconds')||lesson.duration),allowSeek:Boolean(pick(v,'AllowSeek','allowSeek')),allowSpeed:Boolean(pick(v,'AllowSpeed','allowSpeed')??true),requiredWatchPercent:Number(pick(v,'RequiredWatchPercent','requiredWatchPercent')||80)});Object.assign(progress,{currentTime:Number(pick(p,'CurrentTimeSeconds','currentTimeSeconds')||0),maxWatchedTime:Number(pick(p,'MaxWatchedTimeSeconds','maxWatchedTimeSeconds')||0),watchPercent:Number(pick(p,'WatchPercent','watchPercent')||0)});previousTime.value=progress.currentTime;const answeredRows=pick(data,'answeredInteractions','AnsweredInteractions')||[];const answeredMap=new Map(answeredRows.map(row=>[Number(pick(row,'InteractionId','interactionId')),row]));const rows=pick(data,'interactions','Interactions')||[];interactions.value=rows.map(row=>{const answered=answeredMap.get(Number(pick(row,'Id','id'))),rawOptions=pick(row,'Options','options');let options=[];try{options=typeof rawOptions==='string'?JSON.parse(rawOptions):rawOptions||[]}catch{options=[]}return{id:Number(pick(row,'Id','id')),questionId:Number(pick(row,'QuestionId','questionId')),videoId:Number(pick(row,'VideoId','videoId')),time:Number(pick(row,'TimeSeconds','timeSeconds')||0),label:pick(row,'QuestionText','questionText')||'Câu hỏi',description:pick(row,'Description','description')||'',type:pick(row,'QuestionType','questionType')||'SINGLE_CHOICE',required:Boolean(pick(row,'Required','required')),pauseVideo:Boolean(pick(row,'PauseVideo','pauseVideo')),allowSkip:Boolean(pick(row,'AllowSkip','allowSkip')),score:Number(pick(row,'Score','score')||0),attemptLimit:Number(pick(row,'AttemptLimit','attemptLimit')||1),answered:Boolean(answered),attempts:Number(pick(answered,'AttemptNumber','attemptNumber')||0),options:options.map(o=>({code:pick(o,'OptionCode','optionCode'),text:pick(o,'OptionText','optionText')}))}});currentScore.value=answeredRows.reduce((sum,row)=>sum+Number(pick(row,'ScoreAwarded','scoreAwarded')||0),0);answeredRows.forEach(row=>triggered.add(Number(pick(row,'InteractionId','interactionId'))));if(course.id){const detail=await axiosClient.get(`/lms/courses/${course.id}`,{params:{_fresh:Date.now()}});mapCourseContent(detail)}}catch(e){error.value=e.message}finally{loading.value=false}}
function mapCourseContent(data){const chapterRows=pick(data,'chapters','Chapters')||[],lessonRows=pick(data,'lessons','Lessons')||[];chapters.value=chapterRows.map(row=>{const id=Number(pick(row,'Id','id'));return{id,title:pick(row,'Title','title')||'',lessons:lessonRows.filter(x=>Number(pick(x,'ChapterId','chapterId'))===id).map(x=>({id:Number(pick(x,'Id','id')),title:pick(x,'Title','title')||'',duration:Number(pick(x,'DurationSeconds','durationSeconds')||0),completed:Boolean(pick(x,'Completed','completed'))}))}})}
function resumeVideo(){if(!videoRef.value)return;const maxDuration=Number.isFinite(videoRef.value.duration)?videoRef.value.duration:video.duration;videoRef.value.currentTime=Math.min(progress.currentTime,Math.max(0,maxDuration-.25));previousTime.value=videoRef.value.currentTime}
function handleTimeUpdate(){const element=videoRef.value;if(!element||activeQuestion.value)return;const now=element.currentTime;if(!video.allowSeek)progress.maxWatchedTime=Math.max(progress.maxWatchedTime,now);else progress.maxWatchedTime=Math.max(progress.maxWatchedTime,now);progress.currentTime=now;progress.watchPercent=video.duration?Math.min(100,progress.maxWatchedTime/video.duration*100):0;const pending=interactions.value.find(item=>!item.answered&&!triggered.has(item.id)&&shouldTriggerInteraction(previousTime.value,now,item.time));previousTime.value=now;if(pending){triggered.add(pending.id);openQuestion(pending)}if(now-lastSavedAt.value>=10)void saveProgress()}
function protectSeek(){const element=videoRef.value;if(!element||video.allowSeek)return;if(element.currentTime>progress.maxWatchedTime+2){element.currentTime=progress.maxWatchedTime;previousTime.value=progress.maxWatchedTime}}
function protectSpeed(){if(videoRef.value&&!video.allowSpeed)videoRef.value.playbackRate=1}
async function saveProgress(){if(!video.id||savingProgress.value)return;savingProgress.value=true;try{await axiosClient.post('/lms/progress/video',{lessonId:lesson.id,videoId:video.id,currentTime:progress.currentTime,maxWatchedTime:progress.maxWatchedTime,watchPercent:progress.watchPercent});lastSavedAt.value=progress.currentTime}catch(e){error.value=e.message}finally{savingProgress.value=false}}
function markerPercent(time){return video.duration?Math.min(100,time/video.duration*100):0}
function openQuestion(item){if(item.answered&&item.attempts>=item.attemptLimit)return;activeQuestion.value=item;singleAnswer.value='';multipleAnswers.value=[];shortAnswer.value='';answerError.value='';answerResult.value=null;if(item.pauseVideo)videoRef.value?.pause()}
function closeQuestion(){if(canSkipQuestion.value){activeQuestion.value=null;void videoRef.value?.play()}}
async function submitAnswer(){submitting.value=true;answerError.value='';try{const answers=activeQuestion.value.type==='MULTIPLE_CHOICE'?multipleAnswers.value:activeQuestion.value.type==='SHORT_ANSWER'?[shortAnswer.value]:[singleAnswer.value];const result=await axiosClient.post('/lms/answers',{lessonId:lesson.id,videoId:video.id,interactionId:activeQuestion.value.id,questionId:activeQuestion.value.questionId,answers,timeInVideo:activeQuestion.value.time,timeSpent:0});const isCorrect=pick(result,'isCorrect','IsCorrect');const score=Number(pick(result,'scoreAwarded','ScoreAwarded')||0);answerResult.value={isCorrect,score,explanation:pick(result,'explanation','Explanation')};activeQuestion.value.answered=true;activeQuestion.value.attempts=Number(pick(result,'attemptNumber','AttemptNumber')||1);currentScore.value=Number(pick(result,'currentLessonScore','CurrentLessonScore')||currentScore.value+score);await saveProgress()}catch(e){answerError.value=e.message}finally{submitting.value=false}}
function continueVideo(){activeQuestion.value=null;answerResult.value=null;void videoRef.value?.play()}
</script>

<style scoped>
.player-grid{display:grid;grid-template-columns:minmax(0,1fr) 340px}.video-area{min-width:0}.video-stage{height:460px;background:#071922;position:relative;display:grid;place-items:center}.video-stage video{width:100%;height:100%;object-fit:contain;background:#000}.video-empty{display:grid;place-items:center;gap:.6rem;color:#d5e1dc}.video-empty i{font-size:3rem;color:#ffff1a}.video-empty span{color:#93a8a0;font-size:.82rem}.video-marker{position:absolute;bottom:49px;transform:translateX(-50%);width:15px;height:15px;border-radius:50%;border:2px solid white;background:#cd1b1b;box-shadow:0 2px 7px rgba(0,0,0,.3)}.video-marker.answered{background:#07875a}.lesson-meta{padding:1.5rem;display:flex;justify-content:space-between;gap:2rem}.lesson-meta h1{font-size:1.35rem;font-weight:800;margin:.5rem 0}.lesson-meta p{margin:0;color:#71817b}.score{text-align:center}.score strong,.score small{display:block}.score strong{font-size:1.5rem;color:#07875a}.content-panel{border-left:1px solid #e6ece9;max-height:650px;overflow:auto}.chapter{padding:.5rem 1rem 1rem}.chapter>strong{display:block;font-size:.78rem;color:#71817b;text-transform:uppercase;margin:.6rem}.chapter a{display:grid;grid-template-columns:20px 1fr auto;gap:.5rem;padding:.65rem;border-radius:8px;font-size:.84rem}.chapter a.active{background:#e9f6f1;color:#07875a}.chapter a small{color:#8b9994}.interaction-list{display:flex;gap:.7rem;overflow:auto}.interaction-list button{min-width:230px;border:0;background:#f5f8f7;border-radius:10px;padding:.8rem;text-align:left;display:grid;grid-template-columns:auto 24px 1fr;gap:.6rem;align-items:center}.interaction-list button>span{font-weight:800;color:#005099}.interaction-list button small{display:block;color:#84928d}.interaction-list button.answered{background:#e9f6f1}.interaction-list .bi-check-circle-fill{color:#07875a}.modal-backdrop-custom{position:fixed;inset:0;background:rgba(10,31,24,.66);z-index:2000;display:grid;place-items:center;padding:1rem}.question-modal{width:min(590px,100%);padding:2rem;position:relative;max-height:92vh;overflow:auto}.question-modal h2{font-size:1.4rem;font-weight:800;margin-top:1rem}.close{position:absolute;right:1rem;top:1rem;border:0;background:#f3f6f5;width:34px;height:34px;border-radius:8px}.answer{display:flex;align-items:center;gap:.75rem;padding:.8rem;margin:.55rem 0;background:#f7f9f8;border-radius:9px}.answer>span{width:28px;height:28px;border-radius:7px;background:white;display:grid;place-items:center;font-weight:800}.answer-result{text-align:center;padding-top:1rem}.answer-result>i{font-size:3.5rem}.answer-result.correct{color:#07875a}.answer-result.wrong{color:#cd1b1b}.answer-result.pending{color:#8a7000}.answer-result h3{font-size:1.3rem;margin:.6rem 0}.answer-result p{color:#53655f;margin-top:1rem}@media(max-width:1050px){.player-grid{grid-template-columns:1fr}.content-panel{border-left:0;border-top:1px solid #e6ece9}.video-stage{height:50vw;min-height:300px}}@media(max-width:600px){.video-stage{height:290px}.lesson-meta{display:block}.score{display:none}}
</style>
